#!/usr/bin/env python3

import sys
from generateOperatorNames import operatorPrefix

# Each leaf of the tests selects the operators of the 6 kinds used by the unique switch on the Iop
# (vr_gen_iop_switch.h) : a kind is associated to a table generated by generateWrappers.py
opKinds=["plain","cc","ccUnfused","conv","convCC","convCCUnfused"]

def operatorTable(kind, floatConv, soft, rounding, backend, post, ccOnly):
    unfused="Unfused" in kind
    convKind=kind.startswith("conv")
    conv=floatConv and convKind
    if rounding=="FLOAT" and not convKind:
        # with --rounding-mode=float only the double operators are instrumented
        rounding="NEAREST"
        soft=False
    if rounding=="NEAREST" and not (unfused or conv):
        soft=False # the instrumentation of a fused nearest operator gives the same result as without
    if ccOnly and not "cc" in kind.lower():
        post=""
    return operatorPrefix(backend, rounding, post, soft, unfused, conv)

def leaf(floatConv, soft, rounding=None, backend="verrou", post="", ccOnly=False):
    tables=[operatorTable(kind, floatConv, soft, rounding, backend, post, ccOnly) for kind in opKinds]
    return "VR_SELECT_OPERATORS("+", ".join(tables)+")\n"

def floatConvTest(**leafArgs):
    return "\tif(!vr.float_conv){\n%s\t}else{//vr.float_conv\n%s\t}//end float_conv\n"%(leaf(False, **leafArgs), leaf(True, **leafArgs))

def softTest(soft, hard):
    return "\tif(vr.instrument_soft_used || vr.instrument_soft_back_used){\n"+soft+"\t}else{//hard\n"+hard+"\t}//end vr.instrument_soft_used\n"


roundingList=[["NEAREST","NATIVE"],
              ["RANDOM"], ["NEARNESS"],
              ["RANDOM_DET"],["NEARNESS_DET"],
              ["RANDOM_COMDET"],["NEARNESS_COMDET"],
              ["RANDOM_SCOMDET"],["NEARNESS_SCOMDET"],
              ["SR_MONOTONIC"],["SR_SMONOTONIC"],
              ["UPWARD"],["DOWNWARD"],["ZERO"],
              ["AWAY_ZERO"],["FARTHEST"],["FLOAT"],
              ["PRANDOM"], ["PRANDOM_DET"], ["PRANDOM_COMDET"]
              ]

def generateVerrouRounding(handler,roundingList):
    for rounding in roundingList:
        roundingMode=rounding[0]
        checkStr="if(vr.roundingMode==VR_"+roundingMode
        for checkRounding in rounding[1:]:
            checkStr+= " ||  vr.roundingMode==VR_" +checkRounding
        checkStr+="){\n"

        strWrite=checkStr + softTest(floatConvTest(soft=True, rounding=roundingMode), floatConvTest(soft=False, rounding=roundingMode)) + "}\n"
        if roundingMode!="NEAREST":
            handler.write("#ifdef USE_VERROU_OPTIM\n")
        handler.write(strWrite)
        if roundingMode!="NEAREST":
            handler.write("#endif //USE_VERROU_OPTIM\n")

def checkPostbackend(backendName, postBackendList, postBackendName):
    res="vr.backend=="+backendName+" "
    for postBackend in postBackendList:
        if postBackend["postBackendName"]=="":
            continue
        res+= "&& "
        neg=""
        if postBackend["postBackendName"]!=postBackendName:
            neg="! "
        if postBackend["boolCheck"]!=None:
            res+= neg+postBackend["boolCheck"]
    return res




def generateVerrouGeneric(handler, backendEnum="vr_verrou", backendName="verrou", postBackendList=None):
    if postBackendList==None:
        handler.write(softTest(floatConvTest(soft=True), floatConvTest(soft=False)))
    else:
        for postBackend in postBackendList:
            args={"backend":backendName, "post":postBackend["postBackendName"], "ccOnly":postBackend["ccOnly"]}
            res="if(" +checkPostbackend(backendEnum, postBackendList,postBackend["postBackendName"])+"){\n"
            if postBackend["convFloat"]:
                res+=softTest(floatConvTest(soft=True, **args), floatConvTest(soft=False, **args))
            else:
                res+=softTest(leaf(False, True, **args), leaf(False, False, **args))
            res+="}\n"
            handler.write(res)


if __name__=="__main__":

    fileName="vr_gen_select_verrou.h"
    handler=open(fileName,"w")
    handler.write("// Generated by %s\n"%( str(sys.argv)[1:-1] ))
    handler.write("#ifndef DEBUG_PRINT_OP //the switch case with rounding mode during instrumentation is incompatible with DEBUG_PRINT_OP (to make it compatible python code generation need to be adapted)\n")
    generateVerrouRounding(handler,roundingList)
    handler.write("#endif\n")
    generateVerrouGeneric(handler)

    fileName="vr_gen_select_backends.h"
    handler=open(fileName,"w")
    handler.write("// Generated by %s\n"%( str(sys.argv)[1:-1] ))
    generateVerrouGeneric(handler, backendEnum="vr_verrou", backendName="verrou",
                          postBackendList=[{"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True },
                                           {"postBackendName":"check_float_max"  ,"boolCheck":"vr.checkFloatMax", "convFloat":False,"ccOnly":False}
                                           ])

    generateVerrouGeneric(handler, backendEnum="vr_checkdenorm", backendName="checkdenorm",
                          postBackendList= [{"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                            {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                           ])
    handler.write("#ifdef USE_VERROU_VPREC\n")
    generateVerrouGeneric(handler, backendEnum="vr_vprec", backendName="vprec",
                          postBackendList= [ {"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                             {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                                            ])
    handler.write("#endif //USE_VERROU_VPREC\n")

    handler.write("#ifdef USE_VERROU_QUADMATH\n")
    generateVerrouGeneric(handler, backendEnum="vr_mcaquad", backendName="mcaquad",
                          postBackendList= [ {"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                             {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                           ])

    handler.write("#else //USE_VERROU_QUADMATH\n")
    handler.write("""
    if(vr.backend==vr_mcaquad){
            VG_(tool_panic) ( "Verrou compiled without quad support...  \\n");
    }
""")
    handler.write("#endif //USE_VERROU_QUADMATH\n")

